/**
 * KS-719 — PUT /api/privacy/settings and PUT /api/settings/notifications
 * accepted UNAUTHENTICATED writes to a shared `'default'` bucket.
 *
 * All four handlers in this family are `authenticateToken(false)` — optional
 * auth — and each derives its storage key as `req.user?.userId || 'default'`.
 * With no bearer, the two PUTs therefore wrote to the literal key `'default'`,
 * which every other unidentified caller then read back. Not a per-user
 * compromise: there is no user to compromise. It is unauthenticated write
 * access to shared state.
 *
 * Kam ruled option 1 (2026-08-29): require auth on the PUTs; keep optional auth
 * on the GETs so an anonymous caller still gets sensible defaults. The GET-side
 * `'default'` fallback stays deliberately — anonymous READS are the supported
 * behaviour, and the must-succeed case below pins that so a later "just require
 * auth everywhere" pass cannot quietly take it away.
 *
 * These tests dispatch through the real router with the real auth middleware,
 * so they assert behaviour (401/200) rather than the presence of a middleware
 * token in source text. The `'default'` write-key assertion is the one that
 * fails loudest if the fallback is ever reintroduced on a write path.
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import type { Request, Response, Router, RequestHandler } from 'express';
import { configureAuth, authenticateToken, parseTestToken } from '../middleware/auth';
import { createAdminRoutes, type AdminRouteDeps } from '../routes/admin';

// ---------------------------------------------------------------------------
// Helpers — mirrors notifications.test.ts (KS-375), the established pattern
// ---------------------------------------------------------------------------

function buildTestToken(payload: Record<string, unknown>): string {
  return `test_token_${Buffer.from(JSON.stringify(payload)).toString('base64')}`;
}

type CapturedRes = Response & { _status: number; _json: unknown };

function makeRes(onFinish: () => void): CapturedRes {
  const res: any = {
    _status: 200,
    _json: null,
    status(code: number) {
      res._status = code;
      return res;
    },
    json(body: unknown) {
      res._json = body;
      onFinish();
      return res;
    },
    setHeader() {
      return res;
    },
    send(body: unknown) {
      res._json = body;
      onFinish();
      return res;
    },
  };
  return res;
}

function dispatch(
  router: Router,
  opts: { method: string; url: string; headers?: Record<string, string>; body?: unknown },
): Promise<CapturedRes> {
  return new Promise((resolve, reject) => {
    const res = makeRes(() => resolve(res));
    const req = {
      method: opts.method,
      url: opts.url,
      headers: opts.headers || {},
      body: opts.body,
      query: {},
      get(name: string) {
        return (this as any).headers[name?.toLowerCase()];
      },
    } as unknown as Request;
    router(req, res as any, (err: unknown) => (err ? reject(err) : resolve(res)));
  });
}

/**
 * Records every key written so a test can assert WHICH bucket a write landed
 * in — the `'default'` shared bucket being the whole point of KS-719.
 */
function makeRecordingRedis() {
  const privacy = new Map<string, unknown>();
  const notif = new Map<string, unknown>();
  const writes: Array<{ store: 'privacy' | 'notif'; key: string }> = [];
  return {
    writes,
    service: {
      getPrivacySettings: async (key: string) => (privacy.has(key) ? privacy.get(key) : null),
      setPrivacySettings: async (key: string, value: unknown) => {
        writes.push({ store: 'privacy', key });
        privacy.set(key, value);
      },
      getNotificationSettings: async (key: string) => (notif.has(key) ? notif.get(key) : null),
      setNotificationSettings: async (key: string, value: unknown) => {
        writes.push({ store: 'notif', key });
        notif.set(key, value);
      },
    },
  };
}

function buildRouter(redisService: object): Router {
  const passThroughBodyParser: RequestHandler = (_req, _res, next) => next();
  return createAdminRoutes({
    authenticateToken,
    parseTestToken,
    mockBodyParser: passThroughBodyParser,
    query: async () => ({ rows: [], rowCount: 0 }),
    isDbAvailable: () => false,
    redisService,
    services: {},
    log: () => undefined,
  } as unknown as AdminRouteDeps);
}

